import React, { useEffect, useState } from 'react'
import { Button, Card, Descriptions, Empty, Form, Input, InputNumber, Modal, Select, Spin, Statistic, Table, Tabs, Tag, Timeline, message } from 'antd'
import { useParams } from '@umijs/max'
import PageHeader from '../../components/PageHeader'
import { useLocale } from '../../locales'
import { createOrder, createPolicy, createProduct, createTask, deleteOrder, deletePolicy, deleteProduct, generateAIInsight, getProfile } from '../../api/customerProfile'

const field = (name, label, node = <Input />) => <Form.Item key={name} name={name} label={label}>{node}</Form.Item>
export default function ProfileDashboard() {
  const { id } = useParams(); const { t } = useLocale(); const [profile, setProfile] = useState(null); const [loading, setLoading] = useState(true); const [modal, setModal] = useState(null); const [insight, setInsight] = useState(null); const [generating, setGenerating] = useState(false); const [form] = Form.useForm(); const [taskForm] = Form.useForm()
  const load = () => { setLoading(true); return getProfile(id).then((res) => setProfile(res.data)).finally(() => setLoading(false)) }; useEffect(() => { load() }, [id])
  const openModal = (type) => { form.resetFields(); setModal(type) }
  const saveModal = async () => { const values = await form.validateFields(); const actions = { policy: createPolicy, order: createOrder, product: createProduct }; await actions[modal](id, values); message.success(t('common.saveSuccess')); setModal(null); load() }
  const remove = (type, row) => Modal.confirm({ title: t('common.deleteConfirm'), onOk: async () => { await ({ policy: deletePolicy, order: deleteOrder, product: deleteProduct }[type])(id, row.id); message.success(t('common.deleteSuccess')); load() } })
  const createNewTask = async () => { const values = await taskForm.validateFields(); await createTask(id, values); taskForm.resetFields(); message.success(t('profile.taskCreated')) }
  const generate = async () => { setGenerating(true); try { const res = await generateAIInsight(id); setInsight(res.data); message.success(t('profile.insightGenerated')) } finally { setGenerating(false) } }
  const policyColumns = [{ title: t('profile.policyTitle'), dataIndex: 'policyTitle' }, { title: t('common.type'), dataIndex: 'policyType' }, { title: t('profile.policyLevel'), dataIndex: 'policyLevel' }, { title: t('profile.issuingAuthority'), dataIndex: 'issuingAuthority' }, { title: t('common.status'), dataIndex: 'status', render: (v) => <Tag color={v === '有效' ? 'success' : 'default'}>{v}</Tag> }, { title: t('common.action'), render: (_, row) => <Button type="link" danger onClick={() => remove('policy', row)}>{t('common.delete')}</Button> }]
  const orderColumns = [{ title: t('common.projectName'), dataIndex: 'projectName' }, { title: t('common.type'), dataIndex: 'projectType' }, { title: t('profile.amount'), dataIndex: 'orderAmount' }, { title: t('common.status'), dataIndex: 'orderStatus' }, { title: t('common.action'), render: (_, row) => <Button type="link" danger onClick={() => remove('order', row)}>{t('common.delete')}</Button> }]
  const productColumns = [{ title: t('common.name'), dataIndex: 'productName' }, { title: t('common.type'), dataIndex: 'productType' }, { title: t('profile.category'), dataIndex: 'category' }, { title: t('common.status'), dataIndex: 'usageStatus' }, { title: t('profile.annualFee'), dataIndex: 'annualFee' }, { title: t('common.action'), render: (_, row) => <Button type="link" danger onClick={() => remove('product', row)}>{t('common.delete')}</Button> }]
  if (!profile && loading) return <Spin spinning fullscreen />
  const basic = profile?.basicInfo || {}; const business = profile?.businessInfo || {}; const management = profile?.managementInfo || {}
  return <Spin spinning={loading}><PageHeader back eyebrow="PROFILE" title={t('profile.title')} /><Card title={`${t('profile.basicInfo')} - ${basic.customerName}`} style={{ marginBottom: 20 }}><Descriptions column={{ xs: 1, sm: 2, md: 3 }}><Descriptions.Item label={t('customer.code')}>{basic.customerCode}</Descriptions.Item><Descriptions.Item label={t('common.customerName')}>{basic.customerName}</Descriptions.Item><Descriptions.Item label={t('customer.nameEn')}>{basic.customerNameEn}</Descriptions.Item><Descriptions.Item label={t('common.industry')}>{basic.industry}</Descriptions.Item><Descriptions.Item label={t('common.region')}>{basic.region}</Descriptions.Item><Descriptions.Item label={t('common.scale')}>{basic.scale}</Descriptions.Item><Descriptions.Item label={t('common.status')}>{management.statusDesc}</Descriptions.Item><Descriptions.Item label={t('customer.managerName')}>{management.managerName}</Descriptions.Item><Descriptions.Item label={t('profile.joinTime')}>{management.joinTime}</Descriptions.Item></Descriptions></Card><Card title={t('profile.businessOverview')} style={{ marginBottom: 20 }}><div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(140px,1fr))', gap: 16 }}>{[['bidCount', 'bidCount'], ['bidAmount', 'bidAmount'], ['itBidCount', 'itBidCount'], ['orderCount', 'orderCount'], ['revenueContribution', 'revenueContribution'], ['productCount', 'productCount']].map(([key, label]) => <Statistic key={key} title={t(`profile.${label}`)} value={business[key] || 0} />)}</div></Card><Card><Tabs items={[{ key: 'branches', label: t('profile.tabBranches'), children: profile.branches?.length ? <Table rowKey="id" dataSource={profile.branches} pagination={false} columns={[{ title: t('customerTree.nodeName'), dataIndex: 'branchName' }, { title: t('customerTree.nodeType'), dataIndex: 'branchType' }, { title: t('common.region'), dataIndex: 'region' }]} /> : <Empty description={t('profile.noBranches')} /> }, { key: 'policies', label: t('profile.tabPolicies'), children: <><Button type="primary" onClick={() => openModal('policy')} style={{ marginBottom: 12 }}>{t('profile.addPolicy')}</Button><Table rowKey="id" dataSource={profile.policies || []} columns={policyColumns} pagination={false} /></> }, { key: 'orders', label: t('profile.tabOrders'), children: <><Button type="primary" onClick={() => openModal('order')} style={{ marginBottom: 12 }}>{t('profile.addOrder')}</Button><Table rowKey="id" dataSource={profile.orders || []} columns={orderColumns} pagination={false} /></> }, { key: 'products', label: t('profile.tabProducts'), children: <><Button type="primary" onClick={() => openModal('product')} style={{ marginBottom: 12 }}>{t('profile.addProduct')}</Button><Table rowKey="id" dataSource={profile.products || []} columns={productColumns} pagination={false} /></> }, { key: 'decisions', label: t('profile.tabDecisions'), children: profile.decisionChains?.length ? <Table rowKey="id" dataSource={profile.decisionChains} pagination={false} columns={[{ title: t('common.projectName'), dataIndex: 'projectName' }, { title: t('decisionChain.decisionMakerName'), dataIndex: 'decisionMakerName' }, { title: t('common.position'), dataIndex: 'decisionMakerPosition' }, { title: t('decisionChain.decisionStage'), dataIndex: 'decisionStage' }, { title: t('decisionChain.influenceLevel'), dataIndex: 'influenceLevel' }]} /> : <Empty description={t('profile.noDecisionChains')} /> }, { key: 'interactions', label: t('profile.tabInteractions'), children: profile.interactionRecords?.length ? <Timeline items={profile.interactionRecords.map((record) => ({ children: <Card size="small"><Tag>{record.type}</Tag> <span>{record.time}</span><p>{record.content}</p></Card> }))} /> : <Empty description={t('profile.noInteractions')} /> }, { key: 'tasks', label: t('profile.tabTasks'), children: <Form form={taskForm} layout="inline"><Form.Item name="taskName" label={t('profile.taskName')} rules={[{ required: true, message: t('profile.taskNameRequired') }]}><Input placeholder={t('profile.taskNamePlaceholder')} /></Form.Item><Form.Item name="taskType" label={t('profile.taskType')} initialValue="营销"><Select options={[{ value: '营销', label: t('profile.taskTypeMarketing') }, { value: '运营', label: t('profile.taskTypeOperation') }]} /></Form.Item><Form.Item name="assigneeName" label={t('profile.assignee')}><Input /></Form.Item><Button type="primary" onClick={createNewTask}>{t('profile.createTask')}</Button></Form> }, { key: 'ai', label: t('profile.tabAI'), children: <><Button type="primary" loading={generating} onClick={generate}>{t('profile.generateInsight')}</Button>{insight ? <div style={{ marginTop: 16 }}>{['industryOverview', 'customerAnalysis', 'competitiveLandscape', 'opportunitiesAndSuggestions', 'riskAlerts'].map((key) => <Card size="small" title={t(`profile.${key === 'opportunitiesAndSuggestions' ? 'opportunities' : key}`)} style={{ marginBottom: 8 }} key={key}>{insight[key]}</Card>)}</div> : <Empty description={t('profile.aiTip')} />}</> }]} /></Card><Modal open={Boolean(modal)} title={modal === 'policy' ? t('profile.policyDialogTitle') : modal === 'order' ? t('profile.orderDialogTitle') : t('profile.productDialogTitle')} onCancel={() => setModal(null)} onOk={saveModal}><Form form={form} layout="vertical">{modal === 'policy' && <>{field('policyTitle', t('profile.policyTitle'))}{field('policyType', t('profile.policyType'), <Select options={['产业', '财税', '贸易', '金融', '其他'].map((value) => ({ value, label: value }))} />)}{field('policyLevel', t('profile.policyLevel'), <Select options={['国家', '省级', '市级', '行业'].map((value) => ({ value, label: value }))} />)}{field('issuingAuthority', t('profile.issuingAuthority'))}{field('policySummary', t('profile.policySummary'), <Input.TextArea rows={3} />)}{field('impactAnalysis', t('profile.impactAnalysis'), <Input.TextArea rows={2} />)}</>}{modal === 'order' && <>{field('projectName', t('common.projectName'))}{field('projectType', t('profile.projectType'), <Select options={['信息化', '基建', '咨询', '运维', '其他'].map((value) => ({ value, label: value }))} />)}{field('orderAmount', t('profile.orderAmount'), <InputNumber min={0} style={{ width: '100%' }} />)}{field('orderStatus', t('profile.orderStatus'), <Select options={['洽谈中', '已签约', '执行中', '已交付', '已验收', '已终止'].map((value) => ({ value, label: value }))} />)}{field('description', t('common.description'), <Input.TextArea rows={3} />)}</>}{modal === 'product' && <>{field('productName', t('common.name'))}{field('productType', t('profile.productType'), <Select options={['产品', '解决方案'].map((value) => ({ value, label: value }))} />)}{field('category', t('profile.category'), <Input />)}{field('usageStatus', t('profile.usageStatus'), <Select options={['使用中', '已停用', '评估中'].map((value) => ({ value, label: value }))} />)}{field('annualFee', t('profile.annualFee'), <InputNumber min={0} style={{ width: '100%' }} />)}{field('description', t('common.description'), <Input.TextArea rows={2} />)}</>}</Form></Modal></Spin>
}

