import React, { useEffect, useRef, useState } from 'react'
import { Button, Card, Col, Descriptions, Row, Statistic, Tag, message } from 'antd'
import { ProTable } from '@ant-design/pro-components'
import PageHeader from '../../components/PageHeader'
import { useLocale } from '../../locales'
import { getGroup139Status, getReportOverview, getReportRecords, manualReport } from '../../api/groupReport'

export default function ReportDashboard() {
  const { t } = useLocale(); const [overview, setOverview] = useState({}); const [status, setStatus] = useState({}); const [reporting, setReporting] = useState(false); const actionRef = useRef()
  const load = () => Promise.all([getReportOverview(), getGroup139Status()]).then(([a, b]) => { setOverview(a.data || {}); setStatus(b.data || {}) }); useEffect(() => { load() }, [])
  const runReport = async () => { setReporting(true); try { const res = await manualReport({ includeAbnormal: false }); message.success(t('groupReport.reportDone', { batch: res.data.reportBatch, success: res.data.successCount, fail: res.data.failCount })); load(); actionRef.current?.reload() } finally { setReporting(false) } }
  const columns = [{ title: t('groupReport.reportBatch'), dataIndex: 'reportBatch' }, { title: t('common.type'), dataIndex: 'reportType' }, { title: t('common.total'), dataIndex: 'totalCount' }, { title: t('common.success'), dataIndex: 'successCount' }, { title: t('common.fail'), dataIndex: 'failCount' }, { title: t('common.status'), dataIndex: 'status', render: (value) => <Tag color={value === '成功' ? 'success' : value === '失败' ? 'error' : 'warning'}>{value}</Tag> }, { title: t('groupReport.reportTime'), dataIndex: 'reportTime' }]
  return <><PageHeader eyebrow="REPORT" title={t('menu.groupReport')} description={t('groupReport.desc')} /><Row gutter={[20, 20]}>{[['totalReports', 'totalReports'], ['successReports', 'successReports'], ['failReports', 'failReports'], ['abnormalDataCount', 'abnormalData']].map(([key, label]) => <Col xs={24} sm={12} lg={6} key={key}><Card><Statistic title={t(`groupReport.${label}`)} value={overview[key] || 0} /></Card></Col>)}</Row><Card style={{ margin: '20px 0' }} title={<span>{t('groupReport.systemStatus')} <Tag color={status.connected ? 'success' : 'error'}>{status.connected ? t('groupReport.connected') : t('groupReport.disconnected')}</Tag></span>}><Descriptions column={3}><Descriptions.Item label={t('groupReport.systemName')}>{status.systemName}</Descriptions.Item><Descriptions.Item label={t('groupReport.syncStatus')}>{status.syncStatus}</Descriptions.Item><Descriptions.Item label={t('groupReport.lastSyncTime')}>{status.lastSyncTime}</Descriptions.Item></Descriptions><Button type="primary" loading={reporting} onClick={runReport}>{t('groupReport.manualReport')}</Button></Card><ProTable actionRef={actionRef} rowKey="id" search={false} columns={columns} request={async (params) => { const res = await getReportRecords({ page: params.current, size: params.pageSize }); return { data: res.data?.records || [], total: res.data?.total || 0, success: true } }} /> </>
}

